@startuml

class User {
  + UserID : int
  + Name : string
  + Address : string
  + Birthday : date
}

abstract class BusinessOwner {
  + LinkedInAccount : string
}

class PizzaRestaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : double
}

class HungryCustomer {
  + DeliveryAddress : string
}

class Order {
  + OrderID : int
  + OrderDateTime : datetime
  + LatestDeliveryTime : time
  + NumberOfPeople : int
}

class EntertainmentOrder {
  + EntertainmentType : string
  + Duration : int
}

class Entertainer {
  + StageName : string
  + Bio : string
  + PricePer30Min : double
}

class Availability {
  + Day : string
}

class Day {
  + Name : string
}

BusinessOwner --|> User
HungryCustomer --|> User
Entertainer --|> User

BusinessOwner "1" -- "*" PizzaRestaurant : owns
PizzaRestaurant "1" -- "*" Pizza : offers
HungryCustomer "1" -- "*" Order : places
Order "1" -- "1..*" Pizza : contains
Order "1" -- "0..1" EntertainmentOrder : has

Entertainer "1" -- "1..*" Availability : provides
Availability "*" -- "1" Day
Availability "*" -- "1" PizzaRestaurant : for

@enduml

